package org.brightstats.stats;

import java.util.*;
import java.util.function.IntConsumer;

/** Fixed-size group-label permutations for PLS/PLSc; MICOM uses fixed pooled-score moments. */
public final class PlsPermutation {
    private PlsPermutation(){}
    public record Options(int samples,long seed,double significance,RegressionBootstrap.Convention convention,boolean twoSided,boolean retainDraws,boolean configuralConfirmed){
        public Options{Objects.requireNonNull(convention);if(samples<30||samples>100000||!Double.isFinite(significance)||significance<=0||significance>=.5||convention==RegressionBootstrap.Convention.STANDARD&&!twoSided)throw new IllegalArgumentException("Invalid group permutation settings; standard mode supports two-sided group differences.");}
        public static Options defaults(){return new Options(5000,42,.05,RegressionBootstrap.Convention.STANDARD,true,false,false);}
    }
    public record Test(Bootstrap.Parameter parameter,double groupA,double groupB,double difference,double permutationMean,double permutationSd,double lower,double upper,double pValue,boolean referenceZeroDifference,EmpiricalHistogram histogram,double[] distribution){public Test{distribution=distribution==null?null:distribution.clone();}@Override public double[] distribution(){return distribution==null?null:distribution.clone();}}
    public record Invariance(String construct,double originalCorrelation,double permutationMeanCorrelation,double correlationLower,double compositionP,boolean referenceZeroCorrelationDistance,double meanDifference,double meanPermutationMean,double meanLower,double meanUpper,double meanP,double logVarianceRatio,double logVariancePermutationMean,double logVarianceLower,double logVarianceUpper,double varianceP,boolean compositional,boolean equalMeans,boolean equalVariances,String verdict,double[] correlationDraws,double[] meanDraws,double[] logVarianceDraws){
        public Invariance{correlationDraws=copy(correlationDraws);meanDraws=copy(meanDraws);logVarianceDraws=copy(logVarianceDraws);}@Override public double[] correlationDraws(){return copy(correlationDraws);}@Override public double[] meanDraws(){return copy(meanDraws);}@Override public double[] logVarianceDraws(){return copy(logVarianceDraws);}private static double[] copy(double[] values){return values==null?null:values.clone();}
    }
    public record Result(PlsGroups.Point point,Options options,int successful,int failed,Map<String,Integer> failures,List<Test> tests,List<Invariance> micom,List<String> warnings,String sampling,String scoreHandling){public Result{failures=Collections.unmodifiableMap(new LinkedHashMap<>(failures));tests=List.copyOf(tests);micom=List.copyOf(micom);warnings=List.copyOf(warnings);}}
    public static Result fit(double[][] observations,List<PlsSem.Block> blocks,List<PlsSem.Edge> edges,PlsSem.Options modelOptions,PlsGroups.Selection selection,boolean consistent,Options options,IntConsumer progress){
        var context=new PlsGroups.Context(observations,blocks,edges,modelOptions,selection,consistent);var point=context.point;boolean reference=options.convention()==RegressionBootstrap.Convention.REFERENCE_4_1_2_1;int terms=point.parameters().size(),constructs=consistent?0:blocks.size(),width=terms+constructs*3;if((long)width*options.samples()>20000000L||options.retainDraws()&&(long)width*options.samples()>1000000L)throw new IllegalArgumentException("Group permutation output is too large; reduce samples/model size or disable retained draws.");double[] va=context.values(point.groupA()),vb=context.values(point.groupB());double[] originalCorrelation=consistent?null:context.compositions(point.groupA(),point.groupB(),false);double[][] originalMoments=consistent?null:context.pooledMoments(context.a,context.b);List<double[]> accepted=new ArrayList<>();Map<String,Integer> failures=new LinkedHashMap<>();Random generator=new Random(options.seed());long[] seeds=reference?ReferenceResampling.seeds(options.seed(),options.samples()):null;
        for(int attempt=0;attempt<options.samples();attempt++){
            Matrices.interrupted();int[] order=shuffle(reference?new Random(seeds[attempt]):generator,context.data.length,reference),a=Arrays.copyOfRange(order,0,context.a.length),b=Arrays.copyOfRange(order,context.a.length,order.length);
            try{var ga=context.group(selection.nameA(),a,a);var gb=context.group(selection.nameB(),b,b);double[] aa=context.values(ga),bb=context.values(gb),values=new double[width];for(int j=0;j<terms;j++)values[j]=aa[j]-bb[j];if(!consistent){double[] correlation=context.compositions(ga,gb,reference);double[][] moments=context.pooledMoments(a,b);for(int j=0;j<constructs;j++){values[terms+j*3]=correlation[j];values[terms+j*3+1]=moments[j][0];values[terms+j*3+2]=moments[j][1];}}if(!Arrays.stream(values).allMatch(Double::isFinite))throw new IllegalArgumentException("Non-finite permutation statistic.");accepted.add(values);}catch(IllegalArgumentException|ArithmeticException problem){failures.merge(problem.getMessage()==null?problem.getClass().getSimpleName():problem.getMessage(),1,Integer::sum);}if(progress!=null)progress.accept(attempt+1);
        }
        int count=accepted.size(),failed=options.samples()-count;if(count<Math.max(30,(int)Math.ceil(options.samples()*.8)))throw new IllegalArgumentException("Too few usable group permutations: "+count+"/"+options.samples()+"; "+failures);List<Test> tests=new ArrayList<>();boolean zero=false;for(int j=0;j<terms;j++){double[] draws=column(accepted,j);var summary=PermutationInference.evaluate(va[j]-vb[j],draws,options.significance(),options.twoSided(),false,reference);zero|=summary.referenceZeroDifference();tests.add(new Test(point.parameters().get(j),va[j],vb[j],summary.original(),summary.mean(),summary.standardDeviation(),summary.lower(),summary.upper(),summary.pValue(),summary.referenceZeroDifference(),EmpiricalHistogram.of(draws),options.retainDraws()?draws:null));}
        List<Invariance> micom=new ArrayList<>();for(int j=0;j<constructs;j++){double[] correlations=column(accepted,terms+j*3),means=column(accepted,terms+j*3+1),variances=column(accepted,terms+j*3+2);var c=PermutationInference.evaluate(originalCorrelation[j],correlations,options.significance(),false,true,reference);var m=PermutationInference.evaluate(originalMoments[j][0],means,options.significance(),options.twoSided(),false,reference);var v=PermutationInference.evaluate(originalMoments[j][1],variances,options.significance(),options.twoSided(),false,reference);boolean composition=c.original()+1e-12>=c.lower(),equalMean=m.original()>=m.lower()&&m.original()<=m.upper(),equalVariance=v.original()>=v.lower()&&v.original()<=v.upper();String verdict=!options.configuralConfirmed()?"UNCONFIRMED_CONFIGURAL":!composition?"NONE":equalMean&&equalVariance?"FULL":"PARTIAL";zero|=c.referenceZeroDifference()||m.referenceZeroDifference()||v.referenceZeroDifference();micom.add(new Invariance(blocks.get(j).name(),c.original(),c.mean(),c.lower(),c.pValue(),c.referenceZeroDifference(),m.original(),m.mean(),m.lower(),m.upper(),m.pValue(),v.original(),v.mean(),v.lower(),v.upper(),v.pValue(),composition,equalMean,equalVariance,verdict,options.retainDraws()?correlations:null,options.retainDraws()?means:null,options.retainDraws()?variances:null));}
        List<String> warnings=new ArrayList<>();if(failed>0)warnings.add(failed+" group permutations failed and were excluded without replacement; inference is conditional on successful fits.");if(options.samples()<1000)warnings.add("Fewer than 1000 permutations; use a larger run for substantive inference.");if(point.excludedRows()>0)warnings.add(point.excludedRows()+" prepared rows are outside both selected groups.");if(!options.configuralConfirmed()&&!consistent)warnings.add("Configural invariance requires review of indicator coding, model specification and settings; no overall MICOM verdict is asserted until confirmed.");if(consistent)warnings.add("PLSc group contrasts are corrected per group; composite MICOM is not produced for this consistent-permutation workflow.");if(reference)warnings.add("Reference mode retains exceedance/B, order-statistic quantiles, population SD, forward-shuffle seeds and its fixed original within-group standardized correlation basis; standard mode uses pooled correlation inputs and corrected Monte Carlo probabilities.");if(zero)warnings.add("Reference probability helper returns zero for an exactly zero observed difference or exactly unit composite correlation. These outputs are flagged and must not be interpreted as significant; use standard mode.");if(!point.unavailableTargets().isEmpty())warnings.add("Unavailable comparison targets were omitted: "+String.join("; ",point.unavailableTargets()));
        return new Result(point,options,count,failed,failures,tests,micom,warnings,reference?"Reference two-stage seeds; forward Fisher-Yates; fixed group sizes":"java.util.Random reverse Fisher-Yates; fixed group sizes; version 1","Group fits aligned to pooled scores at selected rows. MICOM mean/log-population-variance contrasts use fixed pooled model scores, not separately centered group scores.");
    }
    static int[] shuffle(Random random,int n,boolean forward){int[] rows=java.util.stream.IntStream.range(0,n).toArray();if(forward){for(int i=0;i<n;i++){Matrices.interrupted();int selected=i+random.nextInt(n-i),value=rows[i];rows[i]=rows[selected];rows[selected]=value;}}else for(int i=n-1;i>0;i--){Matrices.interrupted();int selected=random.nextInt(i+1),value=rows[i];rows[i]=rows[selected];rows[selected]=value;}return rows;}
    static double[] column(List<double[]> values,int column){double[] result=new double[values.size()];for(int i=0;i<result.length;i++)result[i]=values.get(i)[column];return result;}
}
